{"implementation":"def solve(case):
    nodes = case['nodes']
    threshold = case['utility_threshold']
    node_map = {node['id']: node for node in nodes}
    children = {}
    for node in nodes:
        pid = node['parent']
        if pid is not None:
            children.setdefault(pid, []).append(node['id'])
    root_id = next(node['id'] for node in nodes if node['parent'] is None)
    retained = []
    def dfs(node_id):
        node = node_map[node_id]
        if node['removable'] and node['utility'] < threshold:
            return
        retained.append(node_id)
        for child_id in children.get(node_id, []):
            dfs(child_id)
    dfs(root_id)
    return {"retained_node_ids": retained, "visit_order": retained}"}
